# ==== HDC on memristive crossbars: PCM / NeuRRAM ReRAM / CMO-HfOx ReRAM (AIHWKit 1.1.0) ====
# Run STAGE = "main" first, then STAGE = "ablation". Results are written to Google Drive
# and the run resumes where it stopped if the session drops (just run the cell again).
# A High-RAM runtime gives more CPU cores = more parallel jobs; no GPU is needed.

STAGE     = "main"                          # "main" or "ablation"
DATASETS  = "isolet,ucihar,mnist,fmnist"
ENC_SEEDS = "0,1,2"                         # independent random encoders
N_CHIPS   = 10                              # independently programmed chips per point
DRIVE_DIR = "/content/drive/MyDrive/hdc_memristive"

import os, subprocess, sys, pathlib
from google.colab import drive
drive.mount("/content/drive")
work = pathlib.Path(DRIVE_DIR); (work / "code").mkdir(parents=True, exist_ok=True)
(work / "results").mkdir(exist_ok=True)

FILES = {'hdc.py': '"""Hyperdimensional computing (HDC) with class prototypes stored in a memristive crossbar.\n\nPipeline\n  1. Encode each sample with a random projection: h = sign(x P), P ~ N(0, 1)^(F x D),\n     giving bipolar query hypervectors that drive the crossbar rows as +/-V pulses.\n  2. Train class prototypes in software: one bundling pass (sum of class hypervectors),\n     then optional perceptron-style retraining epochs (standard in HDC literature).\n  3. L2-normalise each prototype (dot product -> cosine similarity) and quantise it to\n     the chosen precision (fp / k-bit / binary).\n  4. Program the prototypes into an AIHWKit inference tile with a device noise model\n     calibrated on real hardware (PCM, NeuRRAM ReRAM, CMO/HfOx ReRAM), let them drift\n     for time t, and classify by argmax over the analog dot products.\nEvery (device, D, precision, t) point is evaluated over several independently\nprogrammed "chips" (Monte Carlo) so device-to-device spread shows up as variance.\n"""\nfrom __future__ import annotations\n\nimport warnings\nfrom dataclasses import dataclass\n\nimport numpy as np\nimport torch\n\nwarnings.filterwarnings("ignore")\n\n# ----------------------------------------------------------------------------- data\nOPENML = {  # name -> (openml name, version, standard split)\n    "isolet": ("isolet", 1, None),\n    "ucihar": ("har", 1, None),\n    "mnist": ("mnist_784", 1, 60000),\n    "fmnist": ("Fashion-MNIST", 1, 60000),\n}\n\n\ndef load_dataset(name: str, data_home: str = "./data", seed: int = 0):\n    """Returns min-max normalised float32 (Xtr, ytr, Xte, yte) and the class count.\n    MNIST / Fashion-MNIST keep their official 60k/10k split; ISOLET and UCI HAR from\n    OpenML are split 80/20, stratified, with a fixed seed."""\n    if name == "digits":  # offline smoke-test set\n        from sklearn.datasets import load_digits\n        d = load_digits()\n        X, y, n_train = d.data.astype(np.float32), d.target, None\n    else:\n        from sklearn.datasets import fetch_openml\n        oname, ver, n_train = OPENML[name]\n        X, y = fetch_openml(oname, version=ver, return_X_y=True, as_frame=False,\n                            data_home=data_home, parser="auto")\n        X = X.astype(np.float32)\n    y = np.unique(y, return_inverse=True)[1].astype(np.int64)\n    if n_train:\n        Xtr, ytr, Xte, yte = X[:n_train], y[:n_train], X[n_train:], y[n_train:]\n    else:\n        from sklearn.model_selection import train_test_split\n        Xtr, Xte, ytr, yte = train_test_split(X, y, test_size=0.2, stratify=y, random_state=seed)\n    lo, hi = Xtr.min(0), Xtr.max(0)\n    scale = np.where(hi > lo, hi - lo, 1.0)\n    Xtr, Xte = (Xtr - lo) / scale, np.clip((Xte - lo) / scale, 0, 1)\n    return Xtr.astype(np.float32), ytr, Xte.astype(np.float32), yte, int(y.max() + 1)\n\n\n# ----------------------------------------------------------------------------- HDC\nclass Encoder:\n    """Random-projection encoder. With centre=True the training-set feature mean is removed\n    before projection, which strips the common-mode component that non-negative features\n    otherwise put into every hypervector (it wastes ADC range on the crossbar)."""\n\n    def __init__(self, n_features: int, dim: int, seed: int = 0, mean: np.ndarray | None = None):\n        g = torch.Generator().manual_seed(seed)\n        self.P = torch.randn(n_features, dim, generator=g)\n        self.mean = None if mean is None else torch.as_tensor(mean, dtype=torch.float32)\n\n    @torch.no_grad()\n    def __call__(self, X: np.ndarray, bs: int = 4096) -> torch.Tensor:\n        X = torch.as_tensor(X)\n        if self.mean is not None:\n            X = X - self.mean\n        out = torch.empty(len(X), self.P.shape[1], dtype=torch.int8)  # +/-1, 1 byte each\n        for i in range(0, len(X), bs):\n            z = X[i:i + bs] @ self.P\n            out[i:i + bs] = torch.where(z >= 0, 1, -1).to(torch.int8)\n        return out\n\n\n@torch.no_grad()\ndef train_prototypes(H: torch.Tensor, y: np.ndarray, n_classes: int,\n                     retrain_epochs: int = 0, lr: float = 1.0, seed: int = 0) -> torch.Tensor:\n    y = torch.as_tensor(y)\n    M = torch.zeros(n_classes, H.shape[1])\n    for i in range(0, len(y), 8192):  # single-pass bundling\n        M.index_add_(0, y[i:i + 8192], H[i:i + 8192].float())\n    g = torch.Generator().manual_seed(seed)\n    for _ in range(retrain_epochs):\n        for idx in torch.randperm(len(y), generator=g).split(256):\n            Mn = M / M.norm(dim=1, keepdim=True).clamp_min(1e-12)\n            Hb = H[idx].float()\n            pred = (Hb @ Mn.T).argmax(1)\n            wrong = pred != y[idx]\n            if wrong.any():\n                Hw = Hb[wrong]\n                M.index_add_(0, y[idx][wrong], lr * Hw)\n                M.index_add_(0, pred[wrong], -lr * Hw)\n    return M\n\n\ndef quantize(M: torch.Tensor, precision: str) -> torch.Tensor:\n    """Per-class L2 normalisation, then symmetric uniform quantisation to `precision`\n    (\'fp\', \'binary\', or \'Nbit\', N >= 2) with a per-class scale."""\n    M = M / M.norm(dim=1, keepdim=True).clamp_min(1e-12)\n    if precision == "fp":\n        return M\n    if precision == "binary":\n        return torch.where(M >= 0, 1.0, -1.0)\n    bits = int(precision.removesuffix("bit"))\n    levels = 2 ** (bits - 1) - 1  # e.g. 4 bit -> integers in [-7, 7]\n    s = M.abs().amax(dim=1, keepdim=True).clamp_min(1e-12) / levels\n    return torch.round(M / s) * s\n\n\n@torch.no_grad()\ndef accuracy_digital(M: torch.Tensor, H: torch.Tensor, y: np.ndarray, bs: int = 8192) -> float:\n    pred = torch.cat([(H[i:i + bs].float() @ M.T).argmax(1) for i in range(0, len(H), bs)])\n    return (pred.numpy() == y).mean().item()\n\n\n# ----------------------------------------------------------------------------- crossbar\nDEVICES = ["pcm", "reram_wan", "reram_cmo"]\n# Times after programming (s). The NeuRRAM ReRAM model only has published coefficients\n# at 1 s, 1 day and 2 days, so it is never extrapolated; 1 s / 1 day / 2 days are shared\n# by all devices for like-for-like comparison. CMO drift is a log(t) fit (extrapolated\n# beyond its characterisation window at 30 days / 1 year; reported as such).\nT_GRID = {\n    "pcm": [1.0, 3600.0, 86400.0, 172800.0, 2592000.0, 31536000.0],\n    "reram_cmo": [1.0, 3600.0, 86400.0, 172800.0, 2592000.0, 31536000.0],\n    "reram_wan": [1.0, 86400.0, 172800.0],\n}\n\n\ndef _safe_cmo_model(**kw):\n    """AIHWKit\'s CMO/HfOx model takes log10 of the drifted conductance before clamping it,\n    so when scaled-up noise pushes a device below 0 S the read-noise term becomes NaN and\n    poisons the whole column. Clamp to the physical floor g_min first (identical to the\n    original whenever the conductance stays positive, i.e. at nominal noise)."""\n    from math import log, sqrt\n\n    from aihwkit.inference import ReRamCMONoiseModel\n    from torch import randn_like\n\n    class SafeReRamCMONoiseModel(ReRamCMONoiseModel):\n        @torch.no_grad()\n        def apply_drift_noise_to_conductance(self, g_prog, drift_noise_param, t_inference):\n            if t_inference == 0:\n                return g_prog\n            g_mean = g_prog + (self.decay_dict["mean"][0] * log(t_inference) * self.drift_scale)\n            sig_rel = self.decay_dict["std"][0] * log(t_inference) + self.decay_dict["std"][1]\n            g_drift = g_mean + randn_like(g_prog) * sig_rel * self.drift_scale\n            g_drift = g_drift.clamp(min=self.g_min, max=self.g_max)\n            sig_read = (self.read_dict["K"] * torch.log10(g_drift) *\n                        sqrt(log((t_inference + self.read_dict["t_read"]) /\n                                 (2 * self.read_dict["t_read"]))))\n            g_final = g_drift + sig_read * randn_like(g_prog) * self.read_noise_scale\n            return g_final.clamp(min=self.g_min, max=self.g_max)\n\n    return SafeReRamCMONoiseModel(**kw)\n\n\ndef make_inference_config(device: str, periphery: str = "realistic", drift_comp: bool = True,\n                          noise_scale: float = 1.0):\n    from aihwkit.inference import (GlobalDriftCompensation, PCMLikeNoiseModel,\n                                   ReRamCMONoiseModel, ReRamWan2022NoiseModel)\n    from aihwkit.simulator.configs import InferenceRPUConfig\n\n    cfg = InferenceRPUConfig()\n    if device == "pcm":\n        cfg.noise_model = PCMLikeNoiseModel(g_max=25.0, prog_noise_scale=noise_scale,\n                                            read_noise_scale=noise_scale, drift_scale=noise_scale)\n    elif device == "reram_wan":\n        cfg.noise_model = ReRamWan2022NoiseModel(noise_scale=noise_scale)\n    elif device == "reram_cmo":\n        cfg.noise_model = _safe_cmo_model(prog_noise_scale=noise_scale,\n                                          read_noise_scale=noise_scale, drift_scale=noise_scale)\n    else:\n        raise ValueError(device)\n    from aihwkit.simulator.parameters.enums import BoundManagementType, NoiseManagementType\n\n    # each tile\'s weights span the full conductance range (max |w| -> g_max), so every\n    # precision gets the same signal current per device; outputs are rescaled digitally\n    cfg.mapping.weight_scaling_omega = 1.0\n    cfg.mapping.weight_scaling_columnwise = False\n    if periphery == "ideal":       # isolate the device: no DAC/ADC quantisation, no IO noise\n        cfg.forward.is_perfect = True\n    elif periphery == "realistic":\n        # single-shot read with a fixed, pre-calibrated ADC range (see calibrate_input_scale):\n        # 7-bit DAC, 9-bit ADC, output noise as in AIHWKit defaults; no dynamic input\n        # re-normalisation and no iterative re-reads, which a real macro would not do per query\n        cfg.forward.noise_management = NoiseManagementType.NONE\n        cfg.forward.bound_management = BoundManagementType.NONE\n    else:\n        raise ValueError(periphery)\n    cfg.drift_compensation = GlobalDriftCompensation() if drift_comp else None\n    return cfg\n\n\n@torch.no_grad()\ndef calibrate_input_scale(Mq: torch.Tensor, H_cal: torch.Tensor, out_bound: float = 12.0,\n                          max_input_size: int = 512, pct: float = 99.9) -> float:\n    """Read-voltage scale s so that the `pct` percentile of |tile partial sums| on\n    calibration queries lands at the ADC full scale. Done once per programmed model on\n    training data (never on test data), like an ADC range calibration on a real chip."""\n    vals = []\n    for r0 in range(0, Mq.shape[1], max_input_size):\n        W = Mq[:, r0:r0 + max_input_size]\n        W = W / W.abs().max().clamp_min(1e-12)\n        vals.append((H_cal[:, r0:r0 + max_input_size].float() @ W.T).abs().flatten())\n    p = torch.quantile(torch.cat(vals)[:2_000_000], pct / 100.0).item()\n    return min(1.0, out_bound / max(p, 1e-12))\n\n\ndef build_crossbar(Mq: torch.Tensor, rpu_config):\n    from aihwkit.nn import AnalogLinear\n    C, D = Mq.shape\n    layer = AnalogLinear(D, C, bias=False, rpu_config=rpu_config)\n    layer.set_weights(Mq.clone(), None)\n    layer.eval()\n    return layer\n\n\n@torch.no_grad()\ndef accuracy_crossbar(Mq, H, y, rpu_config, times, n_chips: int = 10, seed: int = 0,\n                      bs: int = 2048, in_scale: float = 1.0) -> np.ndarray:\n    """acc[chip, t]: each chip is an independent programming of the same prototypes.\n    Queries are applied as +/- in_scale (read-voltage scaling from the ADC calibration)."""\n    acc = np.zeros((n_chips, len(times)))\n    for c in range(n_chips):\n        torch.manual_seed(seed * 1000 + c)\n        layer = build_crossbar(Mq, rpu_config)\n        layer.program_analog_weights()\n        for k, t in enumerate(times):\n            layer.drift_analog_weights(t)\n            outs = [layer(H[i:i + bs].float() * in_scale) for i in range(0, len(H), bs)]\n            if any(not torch.isfinite(o).all() for o in outs):\n                raise FloatingPointError(f"non-finite crossbar output at t={t} (chip {c})")\n            pred = torch.cat([o.argmax(1) for o in outs])\n            acc[c, k] = (pred.numpy() == y).mean()\n    return acc\n\n\n@dataclass\nclass HDCModel:\n    encoder: Encoder\n    prototypes: torch.Tensor  # float, unnormalised\n    n_classes: int\n', 'sweep_hdc.py': '"""Experiment driver for HDC-on-memristive-crossbar study.\n\nA job = (dataset, encoder seed, D, retrain epochs, centring). It encodes and trains once,\nthen evaluates every precision x device x periphery x noise-scale combination over\nn_chips independent programmings and the device\'s time grid. One jsonl line per\nevaluated combination; jobs already present in the output are skipped (resumable).\n\nStages (presets for the Colab cell):\n  main      all datasets, D 256..8192, R {0, 20}, centred, nominal device noise\n  ablation  centring on/off and device noise x{0.5, 1, 2, 4, 8}, D {256, 1024, 4096}\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport itertools\nimport json\nimport os\nimport time\nfrom concurrent.futures import ProcessPoolExecutor, as_completed\nfrom pathlib import Path\n\nSTAGES = {\n    "main": dict(dims="256,512,1024,2048,4096,8192", retrain="0,20", center="1",\n                 noise="1.0", precisions="fp,4bit,2bit,binary", peripheries="ideal,realistic"),\n    "ablation": dict(dims="256,1024,4096", retrain="20", center="0,1",\n                     noise="0.5,1.0,2.0,4.0,8.0", precisions="4bit,binary", peripheries="realistic"),\n}\n\n\ndef job_key(j: dict) -> str:\n    return hashlib.md5(json.dumps(j, sort_keys=True).encode()).hexdigest()\n\n\ndef done_keys(path: Path) -> set:\n    if not path.exists():\n        return set()\n    return {json.loads(l)["job_key"] for l in path.read_text().splitlines() if l.strip()}\n\n\n_DATA_CACHE: dict = {}\n\n\ndef _worker(j: dict) -> list[dict]:\n    os.environ.setdefault("OMP_NUM_THREADS", "1")\n    import torch\n    torch.set_num_threads(int(os.environ.get("HDC_THREADS", "1")))\n    from hdc import (DEVICES, T_GRID, Encoder, accuracy_crossbar, accuracy_digital,\n                     calibrate_input_scale, load_dataset, make_inference_config, quantize,\n                     train_prototypes)\n\n    t0 = time.time()\n    key = (j["dataset"], j["data_home"])\n    if key not in _DATA_CACHE:\n        _DATA_CACHE.clear()\n        _DATA_CACHE[key] = load_dataset(j["dataset"], j["data_home"])\n    Xtr, ytr, Xte, yte, C = _DATA_CACHE[key]\n    enc = Encoder(Xtr.shape[1], j["dim"], seed=j["enc_seed"],\n                  mean=Xtr.mean(0) if j["center"] else None)\n    Htr, Hte = enc(Xtr), enc(Xte)\n    M = train_prototypes(Htr, ytr, C, retrain_epochs=j["retrain"], seed=j["enc_seed"])\n    H_cal = Htr[torch.randperm(len(Htr), generator=torch.Generator().manual_seed(1))[:5000]]\n    out = []\n    for prec in j["precisions"]:\n        Mq = quantize(M, prec)\n        dig = accuracy_digital(Mq, Hte, yte)\n        s = calibrate_input_scale(Mq, H_cal)\n        for dev, per, ns in itertools.product(DEVICES, j["peripheries"], j["noise"]):\n            times = T_GRID[dev]\n            acc = accuracy_crossbar(Mq, Hte, yte, make_inference_config(dev, per, noise_scale=ns),\n                                    times, n_chips=j["n_chips"], seed=j["enc_seed"],\n                                    in_scale=s if per == "realistic" else 1.0)\n            out.append({\n                "job_key": j["job_key"], "dataset": j["dataset"], "n_classes": C,\n                "enc_seed": j["enc_seed"], "dim": j["dim"], "retrain": j["retrain"],\n                "center": j["center"], "precision": prec, "device": dev, "periphery": per,\n                "noise_scale": ns, "in_scale": s, "digital_acc": dig, "times": times,\n                "acc_mean": acc.mean(0).tolist(), "acc_std": acc.std(0).tolist(),\n                "acc_chips": acc.tolist(),\n            })\n    for r in out:\n        r["job_seconds"] = round(time.time() - t0, 1)\n    return out\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("stage", choices=list(STAGES))\n    ap.add_argument("--datasets", default="isolet,ucihar,mnist,fmnist")\n    ap.add_argument("--enc_seeds", default="0,1,2")\n    ap.add_argument("--n_chips", type=int, default=10)\n    ap.add_argument("--workers", type=int, default=os.cpu_count())\n    ap.add_argument("--outdir", default="results")\n    ap.add_argument("--data_home", default="./data")\n    for k in ["dims", "retrain", "center", "noise", "precisions", "peripheries"]:\n        ap.add_argument(f"--{k}", default=None, help="override the stage preset")\n    a = ap.parse_args()\n    p = {k: (getattr(a, k) or v) for k, v in STAGES[a.stage].items()}\n\n    out = Path(a.outdir)\n    out.mkdir(parents=True, exist_ok=True)\n    path = out / f"{a.stage}.jsonl"\n\n    from hdc import load_dataset\n    for d in a.datasets.split(","):  # download once, before forking workers\n        load_dataset(d, a.data_home)\n\n    jobs = []\n    # large D first so the slowest jobs start early\n    for d, dim, s, r, c in itertools.product(\n            a.datasets.split(","), sorted(map(int, p["dims"].split(",")), reverse=True),\n            map(int, a.enc_seeds.split(",")), map(int, p["retrain"].split(",")),\n            map(int, p["center"].split(","))):\n        j = {"dataset": d, "dim": dim, "enc_seed": s, "retrain": r, "center": bool(c),\n             "precisions": p["precisions"].split(","), "peripheries": p["peripheries"].split(","),\n             "noise": [float(v) for v in p["noise"].split(",")], "n_chips": a.n_chips,\n             "data_home": a.data_home}\n        j["job_key"] = job_key(j)\n        jobs.append(j)\n    todo = [j for j in jobs if j["job_key"] not in done_keys(path)]\n    print(f"[{a.stage}] {len(jobs)} jobs, {len(jobs) - len(todo)} done, running {len(todo)} "\n          f"on {a.workers} workers -> {path}", flush=True)\n    with ProcessPoolExecutor(max_workers=a.workers) as ex, path.open("a") as f:\n        futs = {ex.submit(_worker, j): j for j in todo}\n        for i, fu in enumerate(as_completed(futs), 1):\n            j = futs[fu]\n            try:\n                recs = fu.result()\n            except Exception as e:\n                print(f"FAILED {j[\'dataset\']} D={j[\'dim\']} seed={j[\'enc_seed\']}: {e!r}", flush=True)\n                continue\n            for r in recs:\n                f.write(json.dumps(r) + "\\n")\n            f.flush()\n            best = max(recs, key=lambda r: r["digital_acc"])\n            worst = min(recs, key=lambda r: r["acc_mean"][-1])\n            print(f"[{i}/{len(todo)}] {j[\'dataset\']} D={j[\'dim\']} seed={j[\'enc_seed\']} "\n                  f"R={j[\'retrain\']} centre={j[\'center\']}: best digital {best[\'digital_acc\']:.3f} "\n                  f"({best[\'precision\']}), worst analog {worst[\'acc_mean\'][-1]:.3f} "\n                  f"({worst[\'device\']}/{worst[\'periphery\']}/{worst[\'precision\']}/x{worst[\'noise_scale\']}) "\n                  f"[{recs[0][\'job_seconds\']}s]", flush=True)\n\n\nif __name__ == "__main__":\n    import torch  # noqa: F401  (imported in workers; keeps fork start fast)\n    main()\n'}
for name, txt in FILES.items():
    (work / "code" / name).write_text(txt)

# AIHWKit 1.1.0 ships wheels only up to Python 3.12 and is built against torch 2.10.0,
# while Colab now runs Python 3.13. The experiments therefore run in a separate Python
# 3.12 environment (made with uv, ~1-2 min, reused while the runtime stays alive).
ENV = pathlib.Path("/content/hdc_env")
PY = ENV / "bin" / "python"
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "uv"], check=True)
if not PY.exists():
    subprocess.run([sys.executable, "-m", "uv", "venv", "-q", "-p", "3.12", str(ENV)], check=True)
# runs every time: a no-op when everything is already installed
subprocess.run([sys.executable, "-m", "uv", "pip", "install", "-q", "--python", str(PY),
                "aihwkit==1.1.0", "torch==2.10.0", "torchvision==0.25.0", "scikit-learn", "pandas"],
               check=True)
subprocess.run([str(PY), "-c", "import aihwkit, torch; from aihwkit.simulator import rpu_base; "
                "print('aihwkit', aihwkit.__version__, '| torch', torch.__version__)"], check=True)

cmd = [str(PY), "sweep_hdc.py", STAGE, "--datasets", DATASETS, "--enc_seeds", ENC_SEEDS,
       "--n_chips", str(N_CHIPS), "--outdir", str(work / "results"),
       "--data_home", str(work / "data"), "--workers", str(os.cpu_count())]
log = work / "results" / f"{STAGE}.log"
print("running:", " ".join(cmd), "\nlog:", log)
with open(log, "a") as fh:
    p = subprocess.Popen(cmd, cwd=work / "code", stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                         text=True, env={**os.environ, "PYTHONWARNINGS": "ignore"})
    for line in p.stdout:
        fh.write(line); fh.flush()
        if "Warning" not in line:
            print(line, end="")
print("exit code", p.wait())
